(function(){
  function navH(){var n=document.querySelector('.fpnav');return n?n.getBoundingClientRect().height:0;}
  function closeOverlay(el){
    var ov=el.closest('.modal, .kchp-layer, .sheet, .mmenu, .fpsheet');
    if(!ov) return false;
    var cs=getComputedStyle(ov);
    if(cs.display==='none'||cs.visibility==='hidden') return false;
    var btn=ov.querySelector('.mclose, .kchp-back, [data-close], .close, button[aria-label*="акр"]');
    if(btn){ btn.click(); }
    ov.classList.remove('open','is-open','show','active');
    document.body.classList.remove('modal-open','no-scroll','lock');
    document.documentElement.style.overflow='';
    document.body.style.overflow='';
    return true;
  }
  document.addEventListener('click', function(e){
    var a=e.target.closest && e.target.closest('a[href^="#"]');
    if(!a) return;
    var id=a.getAttribute('href');
    if(id==='#'||id.length<2) return;
    var t=document.querySelector(id);
    if(!t) return;
    e.preventDefault();
    var closed=closeOverlay(a);
    setTimeout(function(){
      var y=t.getBoundingClientRect().top+window.pageYOffset-navH()-14;
      window.scrollTo({top:Math.max(0,y), behavior:'smooth'});
    }, closed?220:0);
  }, true);
})();

